use std::{fs,path::{Path,PathBuf},process::Command,time::{SystemTime,UNIX_EPOCH}};use serde_json::{json,Value};
fn path(label:&str)->PathBuf{std::env::temp_dir().join(format!("atlas-reliability-{label}-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()))}
fn run(p:&Path,args:&[&str])->Value{let o=Command::new(env!("CARGO_BIN_EXE_atlas-native-storage-contract")).arg(args[0]).arg(p).args(&args[1..]).output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));serde_json::from_slice(&o.stdout).unwrap()}
fn copy_dir(a:&Path,b:&Path){fs::create_dir(b).unwrap();for entry in fs::read_dir(a).unwrap(){let entry=entry.unwrap();if entry.file_type().unwrap().is_dir(){copy_dir(&entry.path(),&b.join(entry.file_name()))}else{fs::copy(entry.path(),b.join(entry.file_name())).unwrap();}}}
#[test]fn copy_folder_preserves_original_bytes_notes_board_and_links(){let a=path("src");let b=path("copy");run(&a,&["create-workspace"]);let note=run(&a,&["create-note","Примечание","Исходный текст"]);let id=note["id"].as_str().unwrap();let file=atlas_native_storage_contract::add_file(&a,"binary.bin",b"\0\x7f\xffunique").unwrap();let board=json!({"objects":[{"id":id,"x":10.5,"y":-7.25},{"id":file,"x":30,"y":40}],"edges":[{"id":"edge","from":id,"to":file}],"stacks":[]});run(&a,&["put-board",&board.to_string()]);let before=run(&a,&["get-board"]);copy_dir(&a,&b);assert_eq!(run(&b,&["get-note",id])["text"],"Исходный текст");assert_eq!(run(&b,&["get-board"]),before);let c=rusqlite::Connection::open(b.join("atlas.sqlite3")).unwrap();let rel:String=c.query_row("SELECT path FROM objects WHERE id=?",[&file],|r|r.get(0)).unwrap();assert_eq!(fs::read(b.join(rel)).unwrap(),b"\0\x7f\xffunique");drop(c);run(&b,&["update-note",id,"Копия","Изменённая копия"]);assert_eq!(run(&a,&["get-note",id])["text"],"Исходный текст");fs::remove_dir_all(a).unwrap();fs::remove_dir_all(b).unwrap();}
#[test]fn invalid_copied_database_does_not_overwrite_original_or_file(){let a=path("valid");let b=path("corrupt");run(&a,&["create-workspace"]);let note=run(&a,&["create-note","name","important"]);let id=note["id"].as_str().unwrap();copy_dir(&a,&b);fs::write(b.join("atlas.sqlite3"),b"not a sqlite database").unwrap();let result=Command::new(env!("CARGO_BIN_EXE_atlas-native-storage-contract")).args(["get-note",b.to_str().unwrap(),id]).output().unwrap();assert!(!result.status.success());assert_eq!(run(&a,&["get-note",id])["text"],"important");let notes=fs::read_dir(b.join("notes")).unwrap().next().unwrap().unwrap().path();assert_eq!(fs::read_to_string(notes).unwrap(),"important");fs::remove_dir_all(a).unwrap();fs::remove_dir_all(b).unwrap();}
struct FailsAfterData{left:usize,code:i32}
impl std::io::Read for FailsAfterData{fn read(&mut self,b:&mut[u8])->std::io::Result<usize>{if self.left==0{return Err(std::io::Error::from_raw_os_error(self.code))}let n=self.left.min(b.len()).min(1024);b[..n].fill(7);self.left-=n;Ok(n)}}
#[test]fn source_stream_errors_do_not_replace_existing_file_or_board(){let a=path("read-failure");run(&a,&["create-workspace"]);let n=run(&a,&["create-note","name","note text"]);let note=n["id"].as_str().unwrap();let file=atlas_native_storage_contract::add_file(&a,"file.bin",b"previous bytes").unwrap();let board=json!({"objects":[{"id":note,"x":0,"y":0},{"id":file,"x":1,"y":2}],"edges":[{"id":"edge","from":note,"to":file}],"stacks":[]});run(&a,&["put-board",&board.to_string()]);let before=run(&a,&["get-board"]);let c=rusqlite::Connection::open(a.join("atlas.sqlite3")).unwrap();let rel:String=c.query_row("SELECT path FROM objects WHERE id=?",[&file],|r|r.get(0)).unwrap();drop(c);for code in [28,5]{let mut reader=FailsAfterData{left:4096,code};assert!(atlas_native_storage_contract::replace_file_stream(&a,&file,"file.bin",&mut reader).is_err());assert_eq!(fs::read(a.join(&rel)).unwrap(),b"previous bytes");assert_eq!(run(&a,&["get-board"]),before);assert_eq!(run(&a,&["get-note",note])["text"],"note text");}fs::remove_dir_all(a).unwrap();}
#[test]fn snapshot_is_consistent_and_never_overwrites(){use atlas_native_storage_contract::snapshot_workspace;let a=path("snapshot-source");let b=path("snapshot-dest");run(&a,&["create-workspace"]);let n=run(&a,&["create-note","name","текст"]);let id=n["id"].as_str().unwrap();let file=atlas_native_storage_contract::add_file(&a,"file.bin",b"exact bytes").unwrap();let board=json!({"objects":[{"id":id,"x":1.5,"y":-2},{"id":file,"x":8,"y":9}],"edges":[{"id":"e","from":id,"to":file}],"stacks":[]});run(&a,&["put-board",&board.to_string()]);let expected=run(&a,&["get-board"]);let idx=a.join(".atlas-semantic-native");fs::create_dir(&idx).unwrap();fs::create_dir(idx.join("gen-1")).unwrap();fs::write(idx.join("current"),"gen-1").unwrap();fs::write(idx.join("gen-1/index.faiss"),b"index bytes").unwrap();fs::write(idx.join("gen-1/metadata.json"),b"metadata bytes").unwrap();snapshot_workspace(&a,&b).unwrap();assert_eq!(run(&b,&["get-board"]),expected);assert_eq!(run(&b,&["get-note",id])["text"],"текст");let c=rusqlite::Connection::open(b.join("atlas.sqlite3")).unwrap();let check:String=c.query_row("PRAGMA quick_check",[],|r|r.get(0)).unwrap();assert_eq!(check,"ok");let rel:String=c.query_row("SELECT path FROM objects WHERE id=?",[&file],|r|r.get(0)).unwrap();assert_eq!(fs::read(b.join(rel)).unwrap(),b"exact bytes");assert_eq!(fs::read(b.join(".atlas-semantic-native/gen-1/index.faiss")).unwrap(),b"index bytes");assert!(snapshot_workspace(&a,&b).is_err());assert_eq!(run(&b,&["get-board"]),expected);drop(c);fs::remove_dir_all(a).unwrap();fs::remove_dir_all(b).unwrap();}
#[cfg(unix)] #[test]fn snapshot_rejects_symlinks_without_publication(){use atlas_native_storage_contract::snapshot_workspace;use std::os::unix::fs::symlink;let a=path("snapshot-link");let b=path("snapshot-link-dest");run(&a,&["create-workspace"]);let n=run(&a,&["create-note","name","protected"]);symlink("/etc/passwd",a.join("files/link")).unwrap();assert!(snapshot_workspace(&a,&b).is_err());assert!(!b.exists());assert_eq!(run(&a,&["get-note",n["id"].as_str().unwrap()])["text"],"protected");fs::remove_dir_all(a).unwrap();}
#[test]fn snapshot_rejects_bad_sqlite_without_publication(){use atlas_native_storage_contract::snapshot_workspace;let a=path("snapshot-bad");let b=path("snapshot-bad-dest");run(&a,&["create-workspace"]);fs::write(a.join("atlas.sqlite3"),b"not sqlite").unwrap();assert!(snapshot_workspace(&a,&b).is_err());assert!(!b.exists());assert_eq!(fs::read(a.join("atlas.sqlite3")).unwrap(),b"not sqlite");fs::remove_dir_all(a).unwrap();}
#[test]fn snapshot_includes_committed_wal_while_connection_open(){use atlas_native_storage_contract::snapshot_workspace;let a=path("wal-src");let b=path("wal-dest");run(&a,&["create-workspace"]);let note=run(&a,&["create-note","before","text"]);let id=note["id"].as_str().unwrap();let conn=rusqlite::Connection::open(a.join("atlas.sqlite3")).unwrap();conn.pragma_update(None,"journal_mode","WAL").unwrap();conn.pragma_update(None,"wal_autocheckpoint",0).unwrap();conn.execute("UPDATE objects SET title='after-WAL' WHERE id=?",[id]).unwrap();assert!(a.join("atlas.sqlite3-wal").exists());snapshot_workspace(&a,&b).unwrap();let c=rusqlite::Connection::open(b.join("atlas.sqlite3")).unwrap();let title:String=c.query_row("SELECT title FROM objects WHERE id=?",[id],|r|r.get(0)).unwrap();assert_eq!(title,"after-WAL");let check:String=c.query_row("PRAGMA quick_check",[],|r|r.get(0)).unwrap();assert_eq!(check,"ok");drop(c);drop(conn);fs::remove_dir_all(a).unwrap();fs::remove_dir_all(b).unwrap();}
